#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    // Expect pairs of vertex indices after program name
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 1;
    }
    const int N = 8;               // maximum number of vertices
    int adj[N][N] = {{0}};          // adjacency matrix
    // Parse edges
    for (int i = 1; i < argc; i += 2) {
        char *end;
        long u = strtol(argv[i], &end, 10);
        long v = strtol(argv[i + 1], &end, 10);
        if (u < 0 || u >= N || v < 0 || v >= N) {
            puts("INVALID_INPUT");
            return 1;
        }
        adj[u][v] = 1;
        adj[v][u] = 1;
    }
    int visited[N] = {0};
    int queue[N];
    int component = 0;
    // Find connected components (BFS order)
    for (int start = 0; start < N; ++start) {
        if (!visited[start]) {
            int qhead = 0, qtail = 0;
            queue[qtail++] = start;
            visited[start] = 1;
            printf("%d:", component);
            printf(" { ");
            int first = 1;
            while (qhead < qtail) {
                int u = queue[qhead++];
                if (!first) {
                    putchar(',');
                }
                printf("%d", u);
                first = 0;
                for (int v = 0; v < N; ++v) {
                    if (adj[u][v] && !visited[v]) {
                        visited[v] = 1;
                        queue[qtail++] = v;
                    }
                }
            }
            putchar('}');
            putchar('\n');
            ++component;
        }
    }
    return 0;
}
